import java.util.Scanner;

public class CF_723B {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int length = input.nextInt();
        String str = input.next();

        String pattern = "\\([a-zA-Z_]*\\)";
        String replacedStr = str.replaceAll(pattern, "_");

        String[] splitParts = replacedStr.split("_+");
        int maxPartLength = 0;
        for (String part : splitParts) {
            maxPartLength = Math.max(maxPartLength, part.length());
        }
        System.out.println(maxPartLength);

        int totalCount = 0;
        boolean inside = false;
        int startIdx = -1, endIdx = -1;
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c == '(') {
                inside = true;
                startIdx = i;
            } else if (c == ')' && inside) {
                inside = false;
                endIdx = i;
                String insideStr = str.substring(startIdx + 1, endIdx);
                if (!insideStr.isEmpty()) {
                    String[] partsInside = insideStr.split("_+");
                    totalCount += partsInside.length - (insideStr.startsWith("_") ? 1 : 0);
                }
            }
        }
        System.out.println(totalCount);
    }
}
